import { combatMarkup, combatStatsMarkup } from './battle-ui.js?v=2.0.0';
import { getEnemyLineup } from './combat.js?v=2.0.0';
import { CHARACTERS, TRAITS, EQUIPMENT, STRATEGIES, RECIPES, LEVEL_XP } from './data.js?v=2.0.0';
import { createGame, act, getSynergies, getTeamPower, getEnemy, getUnitStats, validateState, getCharacter, getEquipment } from './engine.js?v=2.0.0';

const paths = {
 star:'M12 2 15 9 22 12 15 15 12 22 9 15 2 12 9 9Z',
 swords:'m4 3 8 8-3 3-8-8V3h3Zm16 0-8 8 3 3 8-8V3h-3ZM4 20l5-5m6 0 5 5M2 16l6 6m8 0 6-6',
 grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',
 book:'M3 4h7l2 2 2-2h7v15h-7l-2 2-2-2H3zM12 6v15',
 hammer:'m14 3 7 7-3 3-3-3-9 11-4-4L13 8l-3-3 4-2Z',
 help:'M9 8a3 3 0 1 1 5 2c-2 1-2 2-2 3m0 4h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',
 reset:'M3 10a9 9 0 1 1 2 8M3 3v7h7',
 coin:'M20 12a8 8 0 1 1-16 0 8 8 0 0 1 16 0ZM12 7v10m3-7c0-3-6-3-6 0s6 1 6 4-6 3-6 0',
 heart:'M12 21 3 12a6 6 0 0 1 9-8 6 6 0 0 1 9 8Z',
 level:'m3 12 9-9 9 9-9 9-9-9Zm4 0 5-5 5 5-5 5-5-5Z',
 users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8Zm10-7a4 4 0 0 1 0 8m3 9v-2a4 4 0 0 0-3-4',
 plus:'M12 5v14M5 12h14',
 lock:'M6 10V7a6 6 0 0 1 12 0v3M4 10h16v11H4zM12 14v3',
 unlock:'M7 10V7a5 5 0 0 1 9-3M4 10h16v11H4zM12 14v3',
 refresh:'M20 7a9 9 0 0 0-15-2L2 8m0-6v6h6m-4 9a9 9 0 0 0 15 2l3-3m0 6v-6h-6',
 arrow:'M4 12h16m-6-6 6 6-6 6',
 shop:'M3 9h18l-2-6H5L3 9Zm1 0v12h16V9M9 21v-8h6v8M3 9a3 3 0 0 0 6 0 3 3 0 0 0 6 0 3 3 0 0 0 6 0',
 bag:'M4 7h16v15H4zM8 7V5a4 4 0 0 1 8 0v2',
 check:'m4 12 5 5L20 6',
 shield:'M12 2 3 6v7c0 5 9 9 9 9s9-4 9-9V6l-9-4Z',
 close:'m6 6 12 12M6 18 18 6',
 crown:'m2 6 5 5 5-8 5 8 5-5-3 13H5L2 6ZM5 22h14',
 route:'M5 5h12a4 4 0 0 1 0 8H7a4 4 0 0 0 0 8h12M5 2v6m14 10v6',
 info:'M12 11v6m0-10h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',
 expand:'M9 3H3v6m12-6h6v6M3 15v6h6m12-6v6h-6',
 clock:'M12 6v6l4 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',
};
const icon = (name,cls='') => `<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.star}"/></svg>`;
const esc = value => String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt = value => Number(value).toLocaleString('zh-CN');
const traitName = id => TRAITS.find(t=>t.id===id)?.name||id;
const rarity = ['','#bac7d7','#8dbb9f','#78a7d4','#b29aca','#d6b77e'];
const saveKey = 'currency-wars-classic-v1';
let saveAvailable=true, recovered=false;
function loadGame(){try{const raw=localStorage.getItem(saveKey);if(raw){const saved=JSON.parse(raw);if(validateState(saved))return saved;recovered=true;}}catch{recovered=true;}return createGame();}
let game=loadGame(), selected=game.units[1]?.uid, tab='battle', modal=null, craft=[], codexCost=0, codexQuery='', battleAnimating=false, toastTimer, battleTimer, previousFocus=null, playback=null, shopOpen=true, enlarged=false;
const app=document.getElementById('app'),modalRoot=document.getElementById('modal-root');
function save(){try{localStorage.setItem(saveKey,JSON.stringify(game));saveAvailable=true;}catch{saveAvailable=false;}}
function toast(message){if(!message)return;const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2800);}
function perform(action,{quiet=false}={}){const result=act(game,action);if(result.ok){save();if(!game.units.some(u=>u.uid===selected))selected=game.units.find(u=>u.zone==='front')?.uid;render();}if(!quiet||!result.ok)toast(result.message);return result;}
function unitCard(unit,kind='front'){
 const c=getCharacter(unit.characterId);return `<button class="unit-card ${selected===unit.uid?'selected':''}" style="--char:${c.color}" data-action="select" data-uid="${unit.uid}" draggable="true" aria-label="选择${c.name}，${unit.star}星" aria-pressed="${selected===unit.uid}"><img src="${c.image}" alt="" draggable="false"><div class="unit-meta"><span class="element-badge">◇ ${c.element}</span><span class="stars">${'★'.repeat(unit.star)}</span></div><div class="unit-info"><h3>${c.name}</h3><div class="unit-tags">${c.traits.map(t=>`<span>${traitName(t)}</span>`).join('')}</div><div class="equipped-icons">${Array.from({length:3},(_,i)=>unit.items[i]?`<span class="equipped-icon" title="${getEquipment(unit.items[i]).name}">${getEquipment(unit.items[i]).icon}</span>`:'<span class="equipped-icon empty">＋</span>').join('')}</div></div></button>`;
}
function emptySlot(zone,index){return `<div class="empty-slot" data-zone="${zone}">${zone==='bench'?`<span>${index+1}</span>`:`${icon(zone==='back'?'plus':'users')}<span>${zone==='front'?'部署角色':'后台协同'}</span><span class="slot-number">SLOT 0${index+1}</span>`}</div>`;}
function row(zone,max){const units=game.units.filter(u=>u.zone===zone);return units.map(u=>unitCard(u,zone)).join('')+Array.from({length:Math.max(0,max-units.length)},(_,i)=>emptySlot(zone,units.length+i)).join('');}
function header(){return `<header class="topbar"><div class="brand">${icon('star','brand-mark')}<div><div class="brand-name">货币战争</div><span class="brand-sub">CURRENCY WARS</span></div><span class="edition">经典 · 回合战斗</span></div><nav class="navigation" aria-label="主要导航">${[['battle','swords','作战筹备'],['workshop','hammer','装备工坊'],['codex','book','角色图鉴']].map(([id,i,name])=>`<button class="nav-item ${tab===id?'active':''}" data-action="tab" data-tab="${id}" ${tab===id?'aria-current="page"':''}>${icon(i)}${name}</button>`).join('')}</nav><div class="top-actions"><span class="save-indicator">${saveAvailable?'进度已保存':'仅本次会话'}</span><button class="icon-button" data-action="fullscreen" title="全屏游玩" aria-label="全屏游玩">${icon('expand')}</button><button class="icon-button" data-action="help" title="玩法指南 (?)" aria-label="玩法指南">${icon('help')}</button><button class="icon-button reset-icon" data-action="restart" title="重新开始" aria-label="重新开始">${icon('reset')}</button></div></header>`;}

function overview(){const plane=Math.ceil(game.round/4);return `<section class="overview"><div><div class="eyebrow">${String(plane).padStart(2,'0')} / ${['启程之地','博弈之间','终局回响'][plane-1]}</div><div class="page-title"><h1>${tab==='battle'?'备战阶段':tab==='workshop'?'装备工坊':'角色档案'}</h1><span class="stage-chip">${game.phase==='ended'?'远征结束':`${plane} - ${(game.round-1)%4+1}`}</span></div></div><div class="overview-route" aria-label="远征进度">${Array.from({length:12},(_,i)=>`<span class="route-dot ${i+1<game.round?'done':i+1===game.round?'current':''} ${(i+1)%4===0?'boss':''}" title="第${i+1}关${(i+1)%4===0?' · 首领':''}"><span>${i+1<game.round?'✓':(i+1)%4===0?'♜':i+1}</span></span>${i<11?'<i class="route-link"></i>':''}`).join('')}</div><div class="resources"><div class="resource life">${icon('heart')}<div><div class="resource-value">${game.hp}<em> / 100</em></div><div class="resource-label">小队生命</div></div></div><span class="resource-separator"></span><div class="resource">${icon('coin')}<div><div class="resource-value">${game.gold}<em class="mint"> +${Math.min(game.strategies.includes('compound')?8:5,Math.floor(game.gold/10))}</em></div><div class="resource-label">金币 / 预计利息</div></div></div></div></section>`;}

function synergies(){return `<section class="panel"><div class="panel-heading"><h2>${icon('grid')}阵容羁绊</h2><span>SYNERGIES</span></div><div class="synergy-list">${getSynergies(game).map(s=>`<button class="synergy ${s.active?'activated':''}" data-action="trait" data-id="${s.id}" title="${s.description}"><span class="trait-symbol"><span>${s.icon}</span></span><div><div class="synergy-name">${s.name}</div><div class="synergy-bars">${s.thresholds.map(n=>`<i class="${s.count>=n?'on':''}"></i>`).join('')}</div></div><span class="synergy-count">${s.count}<span class="muted">/${s.next??s.thresholds.at(-1)}</span></span></button>`).join('')||'<p class="no-items">部署角色以激活羁绊</p>'}</div><p class="side-footnote">同名角色只计一次 · 点击查看效果</p></section>`;}
function strategies(){return `<section class="panel"><div class="panel-heading"><h2>${icon('book')}投资策略</h2><span>${game.strategies.length} / 3</span></div>${game.strategies.map(id=>{const s=STRATEGIES.find(s=>s.id===id);return `<div class="strategy-mini"><span>${s.icon}</span><div><strong>${s.name}</strong><small>${s.description}</small></div></div>`;}).join('')||`<div class="strategy-mini"><span>✧</span><div><strong>故事才刚刚开始</strong><small>第 2、6、10 回合<br>选择你的投资策略</small></div></div>`}</section>`;}
function route(){return `<section class="panel route-panel"><div class="route-head"><h2>远征进度</h2><small class="number gold">${String(game.round).padStart(2,'0')} / 12</small></div><div class="route-steps">${[1,2,3,4].map((n)=>{const round=(Math.ceil(game.round/4)-1)*4+n;return `<span class="route-step ${round<game.round?'done':round===game.round?'current':''}"><span>${n===4?'♜':round<game.round?'✓':String(round).padStart(2,'0')}</span></span>`;}).join('')}</div><div class="route-captions"><span>整备 · 交锋 · 成长</span><span>位面首领</span></div></section>`;}
function board(){const deployed=game.units.filter(u=>u.zone!=='bench').length;return `<section class="board"><div class="board-top"><div class="section-title">${icon('swords')}<h2>前台阵容</h2><span class="tiny-label">直接出战 · 最多 4 人</span></div><span class="team-count">${deployed} <span>/ ${game.level} 已部署</span></span></div><div class="front-row" data-zone="front">${row('front',4)}</div><div class="line-label">后台协同 · 按速度触发专属支援</div><div class="back-row" data-zone="back" style="grid-template-columns:repeat(${Math.max(6,game.units.filter(u=>u.zone==='back').length)},92px)">${row('back',6)}</div><div class="board-footer"><span>${icon('info')}拖动部署 · 点击角色查看技能与换位</span><span>后台不承伤 · 前台全灭即战败</span></div></section>`;}
function benchDock(){return `<div class="bench-dock"><button class="experience-button" data-action="exp" ${game.gold<4||game.level===8?'disabled':''} aria-label="购买经验，4金币"><span>购买经验 <kbd>E</kbd></span><strong><small>Lv.</small>${game.level}</strong><span>${game.level===8?'最高等级':`${game.xp} / ${LEVEL_XP[game.level]}`}</span><div class="experience-track"><i style="width:${game.level===8?100:game.xp/LEVEL_XP[game.level]*100}%"></i></div><b>${icon('coin')} 4</b></button><section class="bench-wrap"><div class="subsection-head"><h2>${icon('users')}备战席 <span class="number muted">${game.units.filter(u=>u.zone==='bench').length} / 8</span></h2><span class="tiny-label">3 张同星角色自动升星</span></div><div class="bench" data-zone="bench">${row('bench',8)}</div></section><button class="shop-toggle ${shopOpen?'active':''}" data-action="shop-toggle" aria-pressed="${shopOpen}">${icon('shop')}<strong>${game.gold}</strong><span>${shopOpen?'收起商店':'打开商店'}</span></button></div>`;}

function shop(){const probabilities={4:[55,32,13,0,0],5:[40,35,20,5,0],6:[27,33,28,10,2],7:[18,28,32,18,4],8:[12,20,30,28,10]};return `<section class="shop"><div class="shop-heading"><h2>${icon('shop')}角色商店 <span class="tiny-label section-sub">RECRUITMENT</span></h2><div class="shop-actions"><button class="secondary-button ${game.locked?'active':''}" data-action="lock" title="${game.locked?'解除锁定':'锁定下回合商店'}" aria-label="${game.locked?'解除商店锁定':'锁定商店'}" aria-pressed="${game.locked}">${icon(game.locked?'lock':'unlock')}</button><button class="secondary-button" data-action="refresh" ${game.gold<(game.strategies.includes('discount')?1:2)?'disabled':''} title="刷新商店 (R)">${icon('refresh')}刷新<span class="price">${game.strategies.includes('discount')?1:2} ${icon('coin')}</span></button></div></div><div class="shop-cards">${game.shop.map((id,i)=>{if(!id)return `<div class="shop-sold">${icon('check')}<span>已招募</span></div>`;const c=getCharacter(id),copies=game.units.filter(u=>u.characterId===id&&u.star===1).length;return `<button class="shop-card" style="--char:${c.color};--rarity:${rarity[c.cost]}" data-action="buy" data-index="${i}" ${game.gold<c.cost?'disabled':''} aria-label="招募${c.name}，${c.cost}金币"><img src="${c.image}" alt="" draggable="false"><span class="cost-badge">${icon('coin')}${c.cost}</span>${copies?`<span class="owned-badge">已拥有 ${copies}/3</span>`:''}<div class="shop-info"><h3>${c.name}</h3><small>${c.traits.map(traitName).join(' · ')}</small></div><span class="buy-hint">招募 ＋</span></button>`;}).join('')}</div><div class="shop-footer"><span>${game.locked?'商店已锁定 · 下回合保留当前角色':'每回合自动刷新 · 锁定可保留心仪角色'}</span><div class="shop-probs"><span class="muted">Lv.${game.level} 概率</span>${probabilities[game.level].map((p,i)=>`<span style="color:${rarity[i+1]}">${p}%</span>`).join('')}</div></div></section>`;}
function detail(){const unit=game.units.find(u=>u.uid===selected);if(!unit)return `<section class="panel selected-panel"><div class="panel-heading"><h2>角色详情</h2></div><p class="no-items">选择一位角色<br>查看技能与调整部署</p></section>`;const c=getCharacter(unit.characterId),stats=getUnitStats(game,unit);return `<section class="panel selected-panel" style="--char:${c.color}"><div class="detail-top"><img src="${c.image}" alt=""><div class="detail-title"><small>角色详情</small><h2>${c.name}</h2><span class="stars">${'★'.repeat(unit.star)}</span></div><span class="detail-role">${c.element} · ${c.role} · ${{front:'前台',back:'后台',bench:'备战'}[unit.zone]}</span></div><div class="detail-body"><div class="detail-stats"><div class="detail-stat"><small>攻击</small><span>${stats.attack}</span></div><div class="detail-stat"><small>生命</small><span>${fmt(stats.hp)}</span></div><div class="detail-stat"><small>速度</small><span>${stats.speed}</span></div></div><button class="detail-skill-button" data-action="character" data-id="${c.id}"><div class="skill-name">${icon('star')}${unit.zone==='back'?'后台赋能':c.skill}</div><p class="skill-desc">${unit.zone==='back'?(c.backlineDescription||c.description):(c.skillDescription||c.description)}</p><small>查看战技 / 终结技 / 天赋详情 ›</small></button><div class="detail-items">${Array.from({length:3},(_,i)=>unit.items[i]?`<button class="item-slot filled" data-action="unequip" data-uid="${unit.uid}" data-index="${i}" title="${getEquipment(unit.items[i]).name}：${getEquipment(unit.items[i]).description} 点击卸下" aria-label="卸下${getEquipment(unit.items[i]).name}">${getEquipment(unit.items[i]).icon}</button>`:'<span class="item-slot" title="从装备仓库选择装备">＋</span>').join('')}</div><div class="unit-controls">${['front','back','bench'].filter(z=>z!==unit.zone).map(z=>`<button class="secondary-button" data-action="move" data-uid="${unit.uid}" data-zone="${z}">${{front:'移至前台',back:'移至后台',bench:'移至备战'}[z]}</button>`).join('')}</div><button class="sell-button" data-action="sell" data-uid="${unit.uid}">出售角色 <span class="gold">+ ${c.cost*3**(unit.star-1)} 金币</span></button></div></section>`;}

function inventory(){return `<section class="panel"><div class="panel-heading"><h2>${icon('bag')}装备仓库</h2><button data-action="tab" data-tab="workshop" title="进入装备工坊" aria-label="进入装备工坊">${icon('expand')}</button></div><div class="inventory">${game.inventory.map((id,i)=>{const e=getEquipment(id);return `<button class="inventory-item" data-action="item" data-index="${i}" title="${e.name}：${e.description}" aria-label="装备${e.name}">${e.icon}</button>`;}).join('')}${Array.from({length:Math.max(0,4-game.inventory.length)},()=>'<span class="inventory-item empty">＋</span>').join('')}</div><p class="inventory-note">点击装备分配给角色 · 工坊内可合成</p></section>`;}
function battlePanel(){const enemy=getEnemy(game),lineup=getEnemyLineup(game.round);const enemies=Array.isArray(lineup)?lineup:(lineup.units||[]);return `<section class="panel battle-panel"><div class="enemy-label"><span>下一场交锋</span><span class="number">${String(game.round).padStart(2,'0')} / 12</span></div><div class="enemy-name">${icon(enemy.boss?'crown':'shield')}${enemy.name}${enemy.boss?'<small class="gold">BOSS</small>':''}</div><div class="encounter-lineup">${enemies.map(e=>`<span title="${esc((e.weaknesses||[]).join(' / '))}">${esc(e.name)}<small>${esc((e.weaknesses||[]).join(' · '))}</small></span>`).join('')}</div><p class="enemy-preview">${enemy.boss?'首领拥有专属技能，注意护盾与治疗。':'合理搭配输出、生存与后台支援。'}</p><button class="battle-button" data-action="battle" ${game.phase!=='prep'?'disabled':''}>${icon('swords')}出战${icon('arrow')}</button><p class="battle-note">回合制自动战斗 · 可暂停 / 逐步 / 加速</p></section>`;}

function battlePage(){return `<div class="workspace"><aside class="left-column">${synergies()}${strategies()}</aside><div class="center-column ${shopOpen?'':'shop-hidden'}">${shop()}${board()}${benchDock()}</div><aside class="right-column">${detail()}${inventory()}${battlePanel()}</aside></div>`;}

function workshop(){const a=getEquipment(game.inventory[craft[0]]),b=getEquipment(game.inventory[craft[1]]),result=a&&b?getEquipment(RECIPES[[a.id,b.id].sort().join('+')]||'hybrid'):null;return `<section class="panel page-panel"><div class="tab-page-head"><div><h2>装备工坊 <span class="tiny-label">EQUIPMENT WORKSHOP</span></h2><p>选择仓库中的两件简易装备，预览并合成进阶装备。</p></div><button class="secondary-button" data-action="tab" data-tab="battle">${icon('arrow')}返回筹备</button></div><div class="workshop-layout"><div><h3>装备仓库 <small>${game.inventory.length} 件</small></h3><div class="workshop-inventory">${game.inventory.map((id,i)=>{const e=getEquipment(id);return `<button class="workshop-item ${craft.includes(i)?'selected':''}" data-action="craft-select" data-index="${i}" ${e.tier!==1?'disabled':''} title="${e.description}"><span>${e.icon}</span><strong>${e.name}</strong><small>${e.tier===1?'简易装备':'进阶装备'}</small></button>`;}).join('')||'<p class="no-items">仓库空空的，卸下装备或赢取补给吧。</p>'}</div><div class="recipe-list"><h3>合成图谱</h3>${Object.entries(RECIPES).map(([key,id])=>`<div class="recipe-row"><span>${key.split('+').map(x=>getEquipment(x).name).join(' ＋ ')}</span><span>${getEquipment(id).name}</span></div>`).join('')}<div class="recipe-row"><span>其他任意两件简易装备</span><span>复合式战斗模块</span></div></div></div><div><div class="crafting-station"><small class="eyebrow">SOMETHING GREATER, TOGETHER</small><div class="crafting-slots"><div class="crafting-slot">${a?a.icon:'＋'}</div><span class="muted">＋</span><div class="crafting-slot">${b?b.icon:'＋'}</div></div><div class="craft-result"><span>${result?result.icon:'◇'}</span><h3>${result?result.name:'等待合成'}</h3><p>${result?result.description:'从左侧选择两件简易装备'}</p><button class="primary-button" data-action="combine" ${!result?'disabled':''}>${icon('hammer')} 确认合成</button></div></div><p class="helper-note">合成会消耗所选的两件简易装备。已穿戴装备可在角色详情中免费卸下。进阶装备无法继续合成。</p></div></div></section>`;}
function codex(){const list=CHARACTERS.filter(c=>(!codexCost||c.cost===codexCost)&&(!codexQuery||`${c.name}${c.element}${c.traits.map(traitName).join('')}`.includes(codexQuery)));return `<section class="panel page-panel"><div class="tab-page-head"><div><h2>角色图鉴 <span class="tiny-label">CHARACTER ARCHIVE</span></h2><p>24 位同行者 · 当前为经典玩法改编数值</p></div><span class="number muted">${list.length} / 24</span></div><div class="codex-controls">${[0,1,2,3,4,5].map(n=>`<button class="filter-button ${codexCost===n?'active':''}" data-action="filter" data-cost="${n}">${n?`${n} 费角色`:'全部角色'}</button>`).join('')}<input id="codex-search" class="search-input" placeholder="搜索角色、属性、羁绊" aria-label="搜索角色" value="${esc(codexQuery)}"></div><div class="codex-grid">${list.map(c=>`<button class="unit-card" style="--char:${c.color}" data-action="character" data-id="${c.id}" aria-label="查看${c.name}"><img src="${c.image}" alt="" loading="lazy"><span class="cost-badge">${icon('coin')}${c.cost}</span><div class="unit-info"><h3>${c.name}</h3><div class="unit-tags">${c.traits.map(t=>`<span>${traitName(t)}</span>`).join('')}</div><small>${c.element} · ${c.role}</small></div></button>`).join('')||'<p class="no-items">没有匹配的角色。</p>'}</div></section>`;}
function footer(){return `<footer class="bottom-bar"><span>非官方同人改编 · 角色素材 © HoYoverse · 回合战斗 v2</span><div class="bottom-links"><button data-action="history">战斗记录</button><button data-action="help">玩法指南</button><a href="https://github.com/wudifeixue/CurrencyWarsClassic" target="_blank" rel="noopener">GitHub ↗</a></div></footer>`;}

function render(){app.innerHTML=header()+`<main class="shell">${overview()}${tab==='battle'?battlePage():tab==='workshop'?workshop():codex()}${footer()}</main>`;fitGame();renderModal();}
function fitGame(){const portrait=innerWidth<900&&innerHeight>innerWidth;document.body.classList.toggle('has-orientation-hint',portrait);document.body.classList.toggle('enlarged',enlarged&&portrait);const availableHeight=innerHeight-(portrait?52:0);const fitted=Math.min(innerWidth/1440,availableHeight/900);const scale=enlarged&&portrait?Math.max(.72,fitted):fitted;const viewport=document.getElementById('game-viewport');viewport.style.width=`${1440*scale}px`;viewport.style.height=`${900*scale}px`;app.style.transform=`scale(${scale})`;document.documentElement.style.setProperty('--battle-scale',Math.min(innerWidth/1440,innerHeight/900));document.getElementById('zoom-toggle').textContent=enlarged?'适应窗口':'放大操作';}
async function fullscreen(){try{if(document.fullscreenElement)await document.exitFullscreen();else if(document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();else toast('当前浏览器不支持全屏，请旋转屏幕或在独立浏览器打开。');}catch{toast('当前浏览器无法进入全屏，请使用浏览器的全屏功能。');}}

function openModal(value){previousFocus=document.activeElement;modal=value;renderModal();}
function closeModal(){modal=null;renderModal();previousFocus?.focus?.();}
function modalFrame(body,{wide=false,close=true,center=false}={}){return `<div class="overlay" data-action="backdrop"><section class="modal ${center?'modal-centered':''}" role="dialog" aria-modal="true" aria-labelledby="modal-heading" tabindex="-1" ${wide?'style="width:min(900px,100%)"':''}>${close?`<button class="icon-button modal-close" data-action="close" aria-label="关闭">${icon('close')}</button>`:''}${body}</section></div>`;}
function renderModal(){let html='';
 if(battleAnimating&&playback){html=combatMarkup(playback,game.lastBattle.enemy,game.round);}
 else if(game.phase==='choice'){const strategy=game.choiceKind==='strategy';html=modalFrame(`<div class="modal-kicker">${strategy?'MAKE YOUR NEXT INVESTMENT':'A GIFT FOR YOUR JOURNEY'}</div><h1 id="modal-heading">${strategy?'机遇，从选择开始。':'下一段旅途的补给。'}</h1><p class="modal-intro">第 ${game.round} 回合 · ${strategy?'从三项投资策略中选择一项，效果持续到远征结束。':'选择一件简易装备，装备给角色或前往工坊合成。'}</p><div class="choice-cards">${game.choices.map((choice,i)=>{const item=strategy?STRATEGIES.find(s=>s.id===choice.id):getEquipment(choice.id);return `<button class="choice-card" data-action="choose" data-index="${i}"><div class="choice-rarity">${strategy?item.rarity+' · 投资策略':'补给 · 简易装备'}</div><span class="choice-icon">${item.icon}</span><h2>${item.name}</h2><p>${item.description}</p><span class="choice-select">选择此项 ${icon('arrow')}</span></button>`;}).join('')}</div>`,{wide:true,close:false});}

 else if(game.phase==='result'){const b=game.lastBattle;html=modalFrame(`<div class="result-emblem">${icon(b.won?'crown':'shield')}</div><div class="modal-kicker">BATTLE REPORT</div><h1 id="modal-heading">${b.won?'战斗胜利':'战斗失利'}</h1><p class="modal-intro">第 ${game.round} 关 · ${esc(b.enemy)} · ${b.combat?`${b.combat.turns} 次行动轮次 · ${b.combat.reason==='timeout'?'超过行动上限':b.won?'敌方全部退场':'前台全部退场'}`:'旧版战报'}</p><div class="result-stats"><div><strong>${b.combat?.stats?.filter(s=>s.side==='ally').reduce((n,s)=>n+(s.damage||0),0)?.toLocaleString('zh-CN')||'—'}</strong><small>实际总伤害</small></div><div><strong>+${b.income}</strong><small>本回合收入</small></div><div><strong>${game.hp}</strong><small>剩余小队生命${b.damage?`（−${b.damage}）`:''}</small></div></div>${combatStatsMarkup(b.combat)}<p class="helper-note">${b.rewards.map(esc).join(' · ')}</p><div class="modal-footer">${b.combat?'<button class="secondary-button" data-action="replay">回看战斗</button>':''}<button class="primary-button" data-action="next">${game.round===12||game.hp===0?'查看远征结果':'继续远征'} ${icon('arrow')}</button></div>`,{close:false,center:true});}

 else if(game.phase==='ended'&&!modal){const won=game.result==='victory';html=modalFrame(`<div class="result-emblem">${icon(won?'crown':'star')}</div><div class="modal-kicker">${won?'CLASSIC NEVER FADES':'EVERY END IS A NEW BEGINNING'}</div><h1 id="modal-heading">${won?'经典，因你而延续。':'下一次，会是更好的选择。'}</h1><p class="modal-intro">${won?'你击败了末日兽，完成全部 12 关远征。':'这场远征暂告一段落。试试不同的羁绊与投资路线。'}</p><div class="result-stats"><div><strong>${game.round}</strong><small>抵达关卡</small></div><div><strong>${game.wins}</strong><small>胜利场数</small></div><div><strong>${game.units.filter(u=>u.zone!=='bench').length}</strong><small>最终部署人数</small></div></div><div class="modal-footer" style="justify-content:center"><button class="secondary-button" data-action="history">查看战斗记录</button><button class="primary-button" data-action="new-game">再来一局 ${icon('reset')}</button></div>`,{close:false,center:true});}
 else if(modal?.type==='help'){html=modalFrame(`<div class="modal-kicker">WELCOME BACK, TRAILBLAZER</div><h1 id="modal-heading">熟悉的博弈，轻装上阵。</h1><p class="modal-intro">一局 12 关，组建你的队伍，击败最终首领。进度会自动保存在当前浏览器。</p><div class="help-grid">${[['01 / 招募与升星','点击商店卡牌招募角色。三张同星角色自动合成更高星级，最高三星。刷新花费 2 金币，锁店可保留到下回合。'],['02 / 部署与羁绊','前台最多 4 人，前台与后台总人数不超过等级。备战角色不参战。点击角色选择位置，或拖动到对应区域；同名角色只计一次羁绊。'],['03 / 装备与合成','点击仓库装备，再选择穿戴角色。每人最多 3 件，点击已装备图标可免费卸下。工坊中两件简易装备可合成进阶装备。'],['04 / 运营与投资','每留 10 金币获得 1 利息，通常上限 5。购买经验提升人口。第 2、6、10 回合选择投资卡，其他补给回合可选择装备。'],['05 / 回合制战斗','角色按速度依次行动。普攻恢复战技点，战技消耗战技点，能量满时释放终结技。护盾、治疗、持续伤害、破韧与追加攻击均实际结算。后台触发专属支援且不承伤，前台全灭即失败。'],['06 / 远征与结算','第 4、8、12 关为首领。战败会扣生命；生命耗尽或最后一关失败则远征结束。稳住经济，升星与升人口同样重要。']].map(([title,text])=>`<div class="help-item"><h3>${title}</h3><p>${text}</p></div>`).join('')}</div><p class="helper-note">快捷键：R 刷新 · E 购买经验 · 空格出战/暂停 · → 单步回放 · ? 查看指南<br>本作为非官方同人改编，采用独立平衡的角色费用、羁绊与技能规则；原版技能被简化为可解释的回合效果。</p><div class="modal-footer"><button class="secondary-button" data-action="restart">重新开始</button><button class="primary-button" data-action="close">准备好了</button></div>`,{wide:true});}
 else if(modal?.type==='restart'){html=modalFrame(`<div class="modal-kicker">A NEW JOURNEY</div><h1 id="modal-heading">开启一场新的远征？</h1><p class="modal-intro">本次第 ${game.round} 回合的进度将被新游戏替换。新一局会重新生成商店与奖励。</p><div class="modal-footer"><button class="secondary-button" data-action="close">继续当前远征</button><button class="primary-button" data-action="new-game">重新开始</button></div>`);}
 else if(modal?.type==='trait'){const t=TRAITS.find(t=>t.id===modal.id),s=getSynergies(game).find(s=>s.id===t.id);html=modalFrame(`<div class="modal-kicker">SYNERGY DETAILS</div><h1 id="modal-heading">${t.icon} ${t.name}</h1><p class="modal-intro">${t.description}</p><div class="help-item" style="margin-top:20px"><h3>激活人数：${t.thresholds.join(' / ')}</h3><p>目前已部署 ${s?.count||0} 名不同角色。前台与后台都计入羁绊，备战席不计入。</p></div><p class="helper-note">拥有此羁绊：${CHARACTERS.filter(c=>c.traits.includes(t.id)).map(c=>c.name).join('、')}</p>`);}
 else if(modal?.type==='item'){const e=getEquipment(game.inventory[modal.index]);if(e)html=modalFrame(`<div class="modal-kicker">EQUIP YOUR TEAM</div><h1 id="modal-heading">${e.icon} ${e.name}</h1><p class="modal-intro">${e.description}</p><p class="helper-note">选择一位角色装备 · 每位角色最多 3 件</p><div class="equip-targets">${game.units.map(u=>{const c=getCharacter(u.characterId);return `<button class="equip-target" data-action="equip" data-uid="${u.uid}" data-index="${modal.index}" ${u.items.length>=3?'disabled':''}><img src="${c.image}" alt=""><strong>${c.name} <span class="gold">${'★'.repeat(u.star)}</span></strong><small>${{front:'前台',back:'后台',bench:'备战席'}[u.zone]} · 装备 ${u.items.length}/3</small></button>`;}).join('')}</div>`);}

 else if(modal?.type==='character'){const c=getCharacter(modal.id);html=modalFrame(`<div class="modal-kicker">CHARACTER COMBAT GUIDE</div><h1 id="modal-heading">${c.name} <small>${c.cost} 费 · ${c.element} · ${c.role}</small></h1><p class="modal-intro">${c.combatDescription||c.description}</p><div class="skill-reference"><article><h3>战技 · ${c.skill}</h3><p>${c.skillDescription||c.description}</p></article><article><h3>终结技 · ${c.ultimate||'终结技'}</h3><p>${c.ultimateDescription||'能量蓄满时自动发动。'}</p></article><article><h3>后台赋能</h3><p>${c.backlineDescription||'按速度触发后台协同效果。'}</p></article><article><h3>基础属性 / 羁绊</h3><p>攻击 ${c.attack} · 生命 ${c.hp}<br>${c.traits.map(traitName).join(' / ')}<br>${c.talentDescription||'升星会提升基础属性；装备与羁绊持续影响技能效果。'}</p></article></div><p class="helper-note">简化技能规则以本页说明与战斗日志为准。前台承担敌人攻击；后台只提供协同，前台全灭则本场失败。</p>`);}

 else if(modal?.type==='history'){html=modalFrame(`<div class="modal-kicker">THE JOURNEY SO FAR</div><h1 id="modal-heading">远征战报</h1><p class="modal-intro">${game.wins} 胜 / ${game.losses} 负 · 当前第 ${game.round} 关</p><div class="battle-logs" style="margin-top:20px;max-height:50vh">${game.history.map(b=>`<div class="battle-log">第 ${String(b.round).padStart(2,'0')} 关 <span class="${b.won?'mint':'gold'}">${b.won?'胜利':'失利'}</span> ${b.turns?`· ${b.turns} 次行动轮次`:''} · 收入 +${b.income}${b.damage?` · 生命 −${b.damage}`:''}</div>`).join('')||'第一场交锋还未开始。'}</div>`);}
 const changed=modalRoot.innerHTML!==html;if(changed){const wasOpen=!!modalRoot.firstChild;const focusAction=modalRoot.contains(document.activeElement)?document.activeElement.dataset.action:null;modalRoot.innerHTML=html;app.inert=!!html;if(html&&(!wasOpen||focusAction))requestAnimationFrame(()=>{const target=focusAction?modalRoot.querySelector(`[data-action="${focusAction}"]:not(:disabled)`):null;(target||modalRoot.querySelector('button:not(:disabled),[tabindex="-1"]'))?.focus();});}
}
function startBattle(){if(battleAnimating||game.phase!=='prep')return;const result=act(game,{type:'battle'});if(!result.ok){toast(result.message);return;}save();beginReplay();}
function beginReplay(){if(!game.lastBattle?.combat){render();return;}clearTimeout(battleTimer);playback={combat:game.lastBattle.combat,cursor:0,speed:2,playing:true};battleAnimating=true;modal=null;renderModal();schedulePlayback();}
function schedulePlayback(){clearTimeout(battleTimer);if(!playback?.playing||!battleAnimating)return;if(playback.cursor>=playback.combat.events.length){playback.playing=false;renderModal();return;}battleTimer=setTimeout(()=>{playback.cursor++;if(playback.cursor>=playback.combat.events.length)playback.playing=false;renderModal();schedulePlayback();},1000/playback.speed);}
function finishPlayback(){clearTimeout(battleTimer);battleAnimating=false;playback=null;render();}
function togglePlayback(){if(!playback)return;playback.playing=!playback.playing;renderModal();schedulePlayback();}
function stepPlayback(){if(!playback)return;clearTimeout(battleTimer);playback.playing=false;playback.cursor=Math.min(playback.cursor+1,playback.combat.events.length);renderModal();}

function handleAction(button){const a=button.dataset.action,i=Number(button.dataset.index),uid=button.dataset.uid;
 switch(a){
 case 'tab':tab=button.dataset.tab;craft=[];render();break;
 case 'select':selected=uid;render();break;
 case 'buy':perform({type:'buy',index:i});break;
 case 'refresh':case 'exp':case 'lock':perform({type:a});break;
 case 'move':perform({type:'move',uid,zone:button.dataset.zone});break;
 case 'sell':perform({type:'sell',uid});break;
 case 'unequip':perform({type:'unequip',uid,itemIndex:i});break;
 case 'battle':startBattle();break;
 case 'replay':beginReplay();break;
 case 'playback-toggle':togglePlayback();break;
 case 'playback-step':stepPlayback();break;
 case 'playback-speed':playback.speed=playback.speed===4?1:playback.speed*2;renderModal();schedulePlayback();break;
 case 'playback-skip':case 'playback-finish':finishPlayback();break;
 case 'shop-toggle':shopOpen=!shopOpen;render();break;
 case 'fullscreen':fullscreen();break;
 case 'zoom':enlarged=!enlarged;fitGame();break;
 case 'next':tab='battle';perform({type:'next'},{quiet:true});break;
 case 'choose':perform({type:'choose',index:i});break;
 case 'help':openModal({type:'help'});break;
 case 'restart':openModal({type:'restart'});break;
 case 'new-game':clearTimeout(battleTimer);game=createGame();selected=game.units[1].uid;tab='battle';modal=null;craft=[];battleAnimating=false;playback=null;shopOpen=true;save();render();toast('新的远征，启程。');break;
 case 'close':closeModal();break;
 case 'backdrop':if(!['choice','result'].includes(game.phase)&&!battleAnimating)closeModal();break;
 case 'trait':openModal({type:'trait',id:button.dataset.id});break;
 case 'item':openModal({type:'item',index:i});break;
 case 'equip':{const result=perform({type:'equip',uid,itemIndex:i});if(result.ok){modal=null;selected=uid;render();}break;}
 case 'craft-select':if(craft.includes(i))craft=craft.filter(x=>x!==i);else craft=[...craft.slice(-1),i];render();break;
 case 'combine':if(craft.length===2){const result=perform({type:'combine',indexA:craft[0],indexB:craft[1]});if(result.ok){craft=[];render();}}break;
 case 'filter':codexCost=Number(button.dataset.cost);render();break;
 case 'character':openModal({type:'character',id:button.dataset.id});break;
 case 'history':openModal({type:'history'});break;
 }
}
document.addEventListener('click',event=>{const button=event.target.closest('[data-action]');if(!button||button.disabled)return;if(button.dataset.action==='backdrop'&&event.target!==button)return;handleAction(button);});
function updateSearch(event){if(event.target.id!=='codex-search'||event.isComposing)return;const position=event.target.selectionStart;codexQuery=event.target.value;render();const input=document.getElementById('codex-search');input.focus();input.setSelectionRange(position,position);}
document.addEventListener('input',updateSearch);
document.addEventListener('compositionend',updateSearch);
document.addEventListener('keydown',event=>{if(battleAnimating&&!event.repeat){if(event.code==='Space'){event.preventDefault();togglePlayback();return;}if(event.key==='ArrowRight'){event.preventDefault();stepPlayback();return;}}if(event.key==='Tab'&&modalRoot.firstChild){const focusables=[...modalRoot.querySelectorAll('button:not(:disabled),a[href],input')];const first=focusables[0],last=focusables.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}return;}if(event.key==='Escape'&&modal&&!battleAnimating){closeModal();return;}if(event.target.matches('input,textarea')||event.ctrlKey||event.metaKey||event.altKey||event.repeat||modalRoot.firstChild)return;if(event.key==='?'){openModal({type:'help'});return;}if(tab!=='battle'||game.phase!=='prep')return;if(event.key.toLowerCase()==='r'){event.preventDefault();perform({type:'refresh'});}else if(event.key.toLowerCase()==='e'){event.preventDefault();perform({type:'exp'});}else if(event.code==='Space'&&!event.target.closest('button')){event.preventDefault();startBattle();}});
document.addEventListener('dragstart',event=>{const card=event.target.closest('[draggable="true"]');if(!card||game.phase!=='prep')return;event.dataTransfer.setData('text/plain',card.dataset.uid);event.dataTransfer.effectAllowed='move';});
document.addEventListener('dragover',event=>{const zone=event.target.closest('[data-zone]');if(zone&&!zone.matches('button')&&game.phase==='prep'){event.preventDefault();zone.classList.add('drag-over');event.dataTransfer.dropEffect='move';}});
document.addEventListener('dragleave',event=>{event.target.closest('[data-zone]')?.classList.remove('drag-over');});
document.addEventListener('drop',event=>{document.querySelectorAll('.drag-over').forEach(el=>el.classList.remove('drag-over'));const zone=event.target.closest('[data-zone]');if(zone&&!zone.matches('button')){event.preventDefault();perform({type:'move',uid:event.dataTransfer.getData('text/plain'),zone:zone.dataset.zone});}});
window.addEventListener('pagehide',save);
